export function groupIssues(issues){const groups=new Map();for(const issue of issues){const key=JSON.stringify([issue.url,issue.id,issue.user]);const group=groups.get(key)||{...issue,fields:[],missingFields:[]};if(!group.fields.includes(issue.field)){group.fields.push(issue.field);group.missingFields.push({name:issue.field,label:issue.fieldAlias||issue.field,kind:issue.kind||'Missing'});}groups.set(key,group);}return [...groups.values()];}
export function alertBody(issue){return 'User: '+issue.user+'\nMissing: '+issue.fields.join(', ')+'\n'+(issue.globalId?'Global ID: '+issue.globalId:'Object ID: '+issue.objectId);}
export function geometryExtent(geometry){if(!geometry)throw Error('This feature has no readable geometry.');const wkid=geometry.spatialReference?.latestWkid||geometry.spatialReference?.wkid;if(![3857,102100,102113].includes(wkid))throw Error('The service did not return the requested map coordinates.');const points=Number.isFinite(geometry.x)?[[geometry.x,geometry.y]]:(geometry.paths||geometry.rings||[geometry.points||[]]).flat();if(!points.length||points.some(p=>!Number.isFinite(p[0])||!Number.isFinite(p[1])))throw Error('No valid feature coordinates were returned.');let xmin=Infinity,ymin=Infinity,xmax=-Infinity,ymax=-Infinity;for(const [x,y] of points){xmin=Math.min(xmin,x);ymin=Math.min(ymin,y);xmax=Math.max(xmax,x);ymax=Math.max(ymax,y);}const pad=Math.max(25,(xmax-xmin)*.1,(ymax-ymin)*.1);return [xmin-pad,ymin-pad,xmax+pad,ymax+pad];}
export function proLink(issue,extent){if(!issue.globalId||!/^\{?[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}\}?$/i.test(issue.globalId)||!Number.isSafeInteger(issue.objectId)||issue.objectId<0)throw Error('A Global ID and valid object ID are required for the Pro connection.');const url=new URL('reg-un-alert://focus');url.searchParams.set('data',JSON.stringify({version:1,layer:issue.url,globalId:issue.globalId,objectId:issue.objectId,globalIdField:issue.globalIdField,fields:issue.fields,extent,wkid:3857}));return url.href;}
